package main

import "fmt"

type Contact struct {
  name string
  age int
}

func main() {
  x := Contact{"py2fun", 42}

  // 访问字段age
  x.age = 8
  fmt.Println(x.age) // 输出字段age
  fmt.Println(x.name) // 输出字段name
}

